'use strict'

const { parseXml } = require('../../../lib/init/xml')

function parsePomXml(filePath) {
  return parseXml(filePath)
}

function updatePomPropertyInFile(filePath, propertyName, newValue) {
  const cds = require('../../../lib/cds')
  const { fs } = cds.utils

  const content = fs.readFileSync(filePath, 'utf8')

  // Match the property tag and replace its value
  // Handles: <propertyName>oldValue</propertyName>
  const regex = new RegExp(`(<${propertyName}>)[^<]*(</${propertyName}>)`, 'g')

  if (!regex.test(content)) {
    return false
  }

  const updated = content.replace(regex, `$1${newValue}$2`)
  fs.writeFileSync(filePath, updated)
  return true
}

function getPomPropertyValue(pomObject, propertyName) {
  const props = pomObject?.properties?.[0]
  if (!props || !props[propertyName]) return null

  let value = props[propertyName]
  if (Array.isArray(value)) value = value[0]
  // xml-js with nativeType+textFn sometimes leaves `{ _text: [<value>] }` for
  // leaf nodes that parsed as numbers. Unwrap to the actual value.
  if (value && typeof value === 'object' && Array.isArray(value._text)) {
    value = value._text[0]
  }
  return value == null ? null : String(value)
}

module.exports = {
  parsePomXml,
  updatePomPropertyInFile,
  getPomPropertyValue,
}
